$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot; $out = Join-Path $root 'test-output'; dotnet publish (Join-Path $root 'Checkup.csproj') -c Release -r win-x64 --self-contained true -p:PublishSingleFile=true -p:IncludeNativeLibrariesForSelfExtract=true -o $out --nologo | Out-Host; if ($LASTEXITCODE -ne 0) { throw "dotnet publish failed with exit code $LASTEXITCODE" }; $exe = Join-Path $out 'Checkup.exe'; if (!(Test-Path -LiteralPath $exe)) { throw 'Checkup executable missing' }; $p = Start-Process -FilePath $exe -PassThru; Start-Sleep -Milliseconds 1800; $p.Refresh(); if ($p.HasExited) { throw "Checkup exited with code $($p.ExitCode)" }; if ($p.MainWindowHandle -eq 0) { Stop-Process -Id $p.Id -Force; throw 'Checkup process started but its main window was not created' }; Stop-Process -Id $p.Id -Force; Write-Output 'PASS: build, publish, and visible launch (Checkup)'
